    &lt;span class="na"&gt;imageUrl&lt;/span&gt;&lt;span class="p"&gt;:&lt;/span&gt; &lt;span class="dl"&gt;'&lt;/span&gt;&lt;span class="s1"&gt;https://example.com/stickers.jpg&lt;/span&gt;&lt;span class="dl"&gt;'&lt;/span&gt;
